"use client";

import { useState } from "react";
import { Copy, Check } from "lucide-react";
import { AnimatePresence, m } from "motion/react";
import { Tooltip } from "@/components/ui/tooltip";
import { useToast } from "@/lib/hooks/use-toast";
import { EASE } from "@/lib/motion";
import { tokenize, type CodeLang } from "./code-highlight";
import { cn } from "@/lib/utils";

interface CodeBlockProps {
  /** Conteúdo bruto do trecho (é o que vai para a área de transferência). */
  code: string;
  /** Linguagem para o realce (padrão: text, sem realce). */
  language?: CodeLang;
  /** Rótulo exibido no cabeçalho (ex.: "curl", "JavaScript", "Payload"). */
  label?: string;
  className?: string;
}

const LANG_LABEL: Record<CodeLang, string> = {
  bash: "curl",
  json: "JSON",
  javascript: "JavaScript",
  text: "Código",
};

/**
 * Bloco de código com realce de sintaxe e botão de copiar (capability
 * doc-code-block). Cores só por token de code theme (sem hex). Feedback de
 * cópia via `useToast` (§4.19/§4.20) — requer `ToastProvider` na árvore.
 * Acessível: botão com `aria-label`, alvo ≥ 40px, foco visível.
 */
export function CodeBlock({ code, language = "text", label, className }: CodeBlockProps) {
  const toast = useToast();
  const [copied, setCopied] = useState(false);
  const tokens = tokenize(code, language);
  const heading = label ?? LANG_LABEL[language];

  async function copy() {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      toast.success("Copiado.");
      window.setTimeout(() => setCopied(false), 1600);
    } catch {
      toast.warning("Não foi possível copiar. Copie manualmente.");
    }
  }

  return (
    <div
      className={cn(
        "rounded-[var(--r-md)] border overflow-hidden my-3",
        className
      )}
      style={{ background: "var(--code-bg)", borderColor: "var(--code-border)" }}
    >
      <div
        className="flex items-center justify-between gap-2 pl-3.5 pr-2 py-1.5 border-b"
        style={{ borderColor: "var(--code-border)" }}
      >
        <span
          className="text-[10px] font-bold uppercase tracking-[0.08em]"
          style={{ color: "var(--code-comment)" }}
        >
          {heading}
        </span>
        <Tooltip label="Copiar" side="left">
          <button
            type="button"
            onClick={copy}
            aria-label={copied ? "Código copiado" : "Copiar código"}
            className="inline-flex items-center justify-center w-10 h-10 rounded-[var(--r-md)] cursor-pointer transition-all hover:text-[var(--brand-yellow)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--brand-yellow)]"
            style={{ color: "var(--code-fg)" }}
          >
            <AnimatePresence mode="wait" initial={false}>
              <m.span
                key={copied ? "ok" : "idle"}
                initial={{ scale: 0.6, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.6, opacity: 0 }}
                transition={{ duration: 0.15, ease: EASE }}
                className="flex items-center justify-center"
              >
                {copied ? (
                  <Check size={16} style={{ color: "var(--success)" }} />
                ) : (
                  <Copy size={16} />
                )}
              </m.span>
            </AnimatePresence>
          </button>
        </Tooltip>
      </div>
      <pre
        className="code-scroll overflow-x-auto px-3.5 py-3 m-0 text-[12.5px] leading-[1.65]"
        style={{ color: "var(--code-fg)" }}
      >
        <code className="font-mono whitespace-pre">
          {tokens.map((t, i) =>
            t.cls ? (
              <span key={i} className={t.cls}>
                {t.text}
              </span>
            ) : (
              <span key={i}>{t.text}</span>
            )
          )}
        </code>
      </pre>
    </div>
  );
}

/**
 * Realçador de sintaxe leve, sem dependência externa (decisão de implementação
 * da capability doc-code-block — ver design.md D4 e tasks 2.2). Tokeniza
 * trechos pequenos de `bash`, `json` e `javascript` em tokens com classe
 * `tok-*`, cujas cores vêm de tokens de code theme em globals.css (sem hex no
 * componente). Não interpreta HTML — retorna apenas dados; o componente
 * renderiza cada token como texto, evitando injeção.
 */

export type CodeLang = "bash" | "json" | "javascript" | "text";

export interface CodeToken {
  /** Classe de realce (`tok-*`) ou null para texto sem realce. */
  cls: string | null;
  text: string;
}

type Rule = [string | null, RegExp];

const RULES: Record<CodeLang, Rule[]> = {
  json: [
    ["tok-property", /"(?:\\.|[^"\\])*"(?=\s*:)/y],
    ["tok-string", /"(?:\\.|[^"\\])*"/y],
    ["tok-keyword", /\b(?:true|false|null)\b/y],
    ["tok-number", /-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/y],
    ["tok-punct", /[{}[\],:]/y],
  ],
  javascript: [
    ["tok-comment", /\/\/[^\n]*/y],
    ["tok-string", /"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`/y],
    [
      "tok-keyword",
      /\b(?:const|let|var|await|async|function|return|if|else|for|of|in|new|import|from|export|true|false|null|undefined)\b/y,
    ],
    ["tok-property", /(?<=\.)[A-Za-z_$][\w$]*/y],
    ["tok-number", /\b\d+(?:\.\d+)?\b/y],
    ["tok-punct", /[{}()[\];:,.=>]+/y],
  ],
  bash: [
    ["tok-comment", /#[^\n]*/y],
    ["tok-string", /"(?:\\.|[^"\\])*"|'[^']*'/y],
    ["tok-keyword", /\bcurl\b/y],
    ["tok-property", /-{1,2}[A-Za-z][\w-]*/y],
    ["tok-number", /\b\d+\b/y],
    ["tok-punct", /[{}[\]|<>\\]/y],
  ],
  text: [],
};

export function tokenize(code: string, lang: CodeLang): CodeToken[] {
  const rules = RULES[lang] ?? RULES.text;
  if (rules.length === 0) return [{ cls: null, text: code }];

  const tokens: CodeToken[] = [];
  let plain = "";
  let pos = 0;

  const flush = () => {
    if (plain) {
      tokens.push({ cls: null, text: plain });
      plain = "";
    }
  };

  while (pos < code.length) {
    let matched = false;
    for (const [cls, re] of rules) {
      re.lastIndex = pos;
      const m = re.exec(code);
      if (m && m.index === pos && m[0].length > 0) {
        flush();
        tokens.push({ cls, text: m[0] });
        pos += m[0].length;
        matched = true;
        break;
      }
    }
    if (!matched) {
      plain += code[pos];
      pos += 1;
    }
  }
  flush();
  return tokens;
}
